#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;

    Fenwick(int n) {
        this->n = n;
        bit.assign(n + 1, 0);
    }

    void add(int i, long long value) {
        for (; i <= n; i += i & -i)
            bit[i] += value;
    }

    long long sumPrefix(int i) {
        long long result = 0;
        for (; i > 0; i -= i & -i)
            result += bit[i];
        return result;
    }

    long long rangeSum(int l, int r) {
        return sumPrefix(r) - sumPrefix(l - 1);
    }
};

int main() {
    Fenwick fenwick(8);

    fenwick.add(3, 5);

    cout << fenwick.sumPrefix(7) << '\n';
    cout << fenwick.rangeSum(1, 7) << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<int> bit;

    Fenwick(int n) {
        this->n = n;
        bit.assign(n + 1, 0);
    }

    void add(int i, int value) {
        for (; i <= n; i += i & -i)
            bit[i] += value;
    }

    int sumPrefix(int i) {
        int result = 0;
        for (; i > 0; i -= i & -i)
            result += bit[i];
        return result;
    }
};

int main() {
    int n;
    cin >> n;

    vector<long long> a(n), compressed;
    for (long long &x : a) {
        cin >> x;
        compressed.push_back(x);
    }

    sort(compressed.begin(), compressed.end());
    compressed.erase(unique(compressed.begin(), compressed.end()), compressed.end());

    Fenwick fenwick(compressed.size());
    long long inversions = 0;

    for (int i = 0; i < n; ++i) {
        int rank = lower_bound(compressed.begin(), compressed.end(), a[i]) - compressed.begin() + 1;
        long long smallerOrEqual = fenwick.sumPrefix(rank);
        inversions += i - smallerOrEqual;
        fenwick.add(rank, 1);
    }

    cout << inversions << '\n';
    return 0;
}
